def render(results):
    rows = "".join(
        f"<tr><td>{r['name']}</td><td>{r['status']}</td><td>{r['ms']} ms</td></tr>" for r in results)
    return ('<table class="results"><thead><tr><th>Test</th><th>Status</th><th>Time</th></tr></thead>'
            f"<tbody>{rows}</tbody></table>")


